import type {
  BuiltInMcpDomain,
  BuiltInMcpServerConfig,
} from '@mcp/shared/types.js'
import type { ResolvedUserMcpServer } from '@shared/userMcp/types.js'
import type { ProviderConditionSnapshot } from '@shared/types/providerConditions.js'
import type { AgentProviderRuntime, SessionKind } from '@shared/types/providerKind.js'
import type { KillCaller } from '@shared/lifecycle/events.js'

// Re-export the provider/session kind source of truth so callers that
// already import session types from here keep one import. The canonical
// definition (and the rationale for the AgentProviderKind vs SessionKind
// split) lives in providerKind.ts — see that file before adding a kind.
export type {
  AgentProviderKind,
  AgentProviderRuntime,
  SessionKind,
} from '@shared/types/providerKind.js'

// WHY recovery types live at the neutral shared boundary: main owns the
// operation, preload transports it, and the renderer consumes it. Defining a
// look-alike at each layer would make the most important fields in the restart
// protocol (the stable local id and readiness revision) vulnerable to silent
// drift. Provider history ids remain launch hints; they are intentionally not
// part of the ownership comparison represented by SessionBackendSnapshot.
export type SessionInputReadiness = {
  ready: boolean
  revision: number
  /**
   * Why input is unavailable, specific enough to act on.
   *
   * WHY `composer-occupied` is carried separately rather than folded into the
   * catch-all `provider-not-ready` (#683): every non-ready verdict used to
   * collapse here, so a session blocked because the user's own text is sitting
   * in the provider's composer looked exactly like one that was merely slow to
   * boot. Both rendered as "waiting for agent". That state does not clear on
   * its own — deliberately, because the gate must never overwrite a human
   * draft — so the only signal the user got was a pane that stayed dead, with
   * the actual cause and the way out both invisible. Measured before this
   * change: 19 of 216 sessions ended still blocked, the longest for 47 hours.
   *
   * The distinction has to survive the main -> renderer boundary because it is
   * the difference between "wait" and "there is something you need to clear".
   * Everything else stays collapsed: a caller cannot do anything differently
   * about replay-pending versus composer-unpainted.
   */
  reason?:
    | 'starting'
    | 'replaying-history'
    | 'provider-not-ready'
    | 'composer-occupied'
    | 'ready'
}

// Provider runtimes know *when* their composer is safe, but they do not own
// the cross-process ordering counter. SessionManager adds `revision` when it
// folds this provider fact into the level-triggered backend snapshot.
export type AgentInputReadiness = Omit<SessionInputReadiness, 'revision'>

export type SessionBackendSnapshot = {
  sessionId: string
  /**
   * Identity of the concrete registered backend lifetime, when one exists.
   *
   * WHY this is not derivable from `sessionId`: renderer panes keep the same
   * local id across adoption and replacement, while delayed observations must
   * remain attributable to the exact process that produced them. Recovery is
   * also the only bootstrap path for an already-live backend and emits no new
   * `session:started` edge, so omitting this value leaves a reloaded renderer
   * permanently unable to name that run. It is optional only because a
   * `spawning` snapshot can exist before SessionManager has registered a
   * backend (and older transports/recordings do not carry the field). Every
   * `live` snapshot produced by current main includes it.
   */
  sessionRunId?: string
  kind: SessionKind
  /** Alternate agent execution runtime. Absent means the provider's normal
   * structured runtime; plain terminal sessions never carry this field. */
  providerRuntime?: AgentProviderRuntime
  cwd: string
  lifecycle: 'spawning' | 'live'
  input: SessionInputReadiness
  /** Main's effective launch-time MCP scope for an agent backend. This is an
   *  observed backend fact, not the renderer's requested policy. It is absent
   *  for terminal sessions, which never receive built-in MCP configuration. */
  builtInMcpDomains?: BuiltInMcpDomain[]
  /** Ids of the user MCP servers (#1143) this backend was launched with. Like
   *  `builtInMcpDomains`, an observed launch fact reported by main, never the
   *  renderer's request: main applies defaults, secrets and support at launch,
   *  and an adopted process keeps whatever it started with. */
  userMcpServerIds?: string[]
  /** Main-owned logical summary identity when this backend exposes TLDR. */
  tldrIdentity?: string
}

export type SessionRecoverOptions = {
  sessionId: string
  kind?: SessionKind
  providerRuntime?: AgentProviderRuntime
  cwd: string
  cols?: number
  rows?: number
  resumeSessionId?: string
  dangerousMode?: boolean
  useProxy?: boolean
  recoverTmuxName?: string
  tldrIdentity?: string
  builtInMcpDomains?: BuiltInMcpDomain[]
  /** The pane's explicit per-agent user MCP choices (bare server id → on/off).
   *  Used only if recovery has to START a backend; an adopted one keeps the
   *  servers it was launched with. */
  userMcpOverrides?: Record<string, boolean>
  /**
   * Opaque renderer-generated generation for this recovery admission.
   *
   * WHY the stable ownership tuple is insufficient: a timeout message for an
   * earlier recovery can arrive after replacement compensation has published a
   * new claim under the same sessionId/kind/cwd. Cancellation must name the
   * generation whose deadline fired or it can tear down the later restore.
   */
  recoveryToken?: string
  /**
   * Bootstrap-only authority to reclaim an unpersisted Codex replacement.
   * Ordinary wake/retry calls must remain fenced while a same-pane replacement
   * is active; only rehydrate knows the predecessor ID is still durable.
   */
  reclaimPendingReplacement?: boolean
}

export type SessionOwnershipOptions = Pick<
  SessionRecoverOptions,
  'sessionId' | 'kind' | 'providerRuntime' | 'cwd'
>

/**
 * The `session:kill-owned` request: the ownership proof plus who asked.
 *
 * WHY a separate type rather than adding `caller` to SessionOwnershipOptions:
 * that tuple is also the durable ownership record main stores on Codex
 * replacement reservations and redirects (predecessorOwnership /
 * successorOwnership). "Who asked for this kill" is a property of one
 * request, not of ownership, and must not be persisted into those records.
 *
 * Optional on the wire so an older or foreign caller still kills; main
 * journals the gap as `caller: 'unknown'` (#1135).
 */
export type SessionKillOptions = SessionOwnershipOptions & {
  caller?: KillCaller
}

export type SessionRecoveryCancellationOptions = SessionOwnershipOptions & {
  recoveryToken: string
}

/** The one message a renderer shows for a provider that would not start.
 *
 *  WHY a fixed string and never the exception's own text: binary launch
 *  errors can carry environment values, proxy URLs or scoped MCP tokens, and
 *  the pane renders whatever lands in `processError`. Main's recovery path
 *  (SessionManager.recoverSession) and the renderer's reload path
 *  (reloadAgentSessions, #1239) both reach a failed provider start; sharing
 *  the constant keeps the two from drifting into one safe and one leaky
 *  surface. The raw error stays in main's performance journal. */
export const SESSION_START_FAILED_MESSAGE = 'Session failed to start. Check provider setup and retry.'

/** How MissingWorkspaceDirectoryError's message starts, shared so the
 *  renderer can recognise it on the far side of IPC.
 *
 *  WHY a message prefix and not an error code: `ipcRenderer.invoke` relays
 *  only the message (wrapped as "Error invoking remote method '…': …"); the
 *  class, name and any custom field are lost. This is the one start failure
 *  whose text main deems safe to show (see workspaceDirectory.ts), and the
 *  one a retry can never fix, so Undo Close must tell it apart from a
 *  provider failure (#1264 review B, R2-1). Changing the text in one place
 *  and not the other would silently turn a deleted worktree back into a
 *  poisoned undo-stack head; sharing the constant prevents that drift. */
export const MISSING_WORKSPACE_FOLDER_PREFIX = 'Workspace folder is missing: '

/** How main's refusal to save a workspace.json it could not read starts
 *  (#1263 review C). That refusal is sticky for the whole process
 *  (WorkspaceFileStore.readOnlyReason is never cleared), so the renderer must
 *  not tell the user a later save will succeed. Shared because IPC relays
 *  only the message text. */
export const WORKSPACE_READ_ONLY_PREFIX = 'Workspace file is read-only this session: '

/** How ProviderCliNotFoundError's message ends after `<kind>`, shared for
 *  the same reason as MISSING_WORKSPACE_FOLDER_PREFIX: the renderer must
 *  recognise this curated, secret-free sentence through the IPC wrapper and
 *  show it, because it names the fix (File › Setup…) (#1286 review C2). */
export const PROVIDER_CLI_NOT_FOUND_SUFFIX = ' CLI not found. Open Setup (File › Setup…) to install it or enter its path.'

/** The actionable message for a Claude proxy (mitmproxy) that would not
 *  start, and how to recognise one. Shared since #1267: main now launders
 *  session:spawn rejections, so the raw mitmproxy text no longer reaches the
 *  renderer, and main must hand over the guidance itself.
 *
 *  WHY the message lists both restart AND the settings toggle: Proxy
 *  Streaming is an exposed setting ("Proxy-Streamed Semantic Rendering"), so
 *  the user has a working escape hatch. Restart first, because the packaged
 *  case is usually a transient mitmproxy startup race; disabling is the
 *  durable fallback where the proxy cannot run at all. */
export const CLAUDE_PROXY_STARTUP_FAILED_MESSAGE = 'Claude proxy startup failed. Restart Agent Code after rebuilding, or disable Proxy-Streamed Semantic Rendering in settings if the proxy will not start in this environment.'

export function isClaudeProxyStartupFailure(raw: string): boolean {
  return raw.includes('Timed out waiting for mitmproxy')
    || raw.includes('Unable to locate mitm')
    || raw.includes('mitmdump')
}

export type SessionRecoverFailureCode =
  | 'ownership-conflict'
  | 'cancelled'
  | 'start-failed'

export type SessionRecoverResult =
  | {
      ok: true
      /** `adopted`: main already owned a live backend. `spawned`: this call
       *  started one. `joined`: this call attached to a recovery another
       *  caller had already started (#772) — the backend is being spawned,
       *  but not by this caller, so a readiness deadline on THIS call must
       *  never be allowed to kill it. */
      disposition: 'adopted' | 'spawned' | 'joined'
      snapshot: SessionBackendSnapshot
      tmuxName?: string
    }
  | {
      ok: false
      code: SessionRecoverFailureCode
      retryable: boolean
      message: string
      actual?: Pick<SessionBackendSnapshot, 'kind' | 'cwd' | 'lifecycle'>
    }

// ---------------------------------------------------------------------------
// AgentSession contract (#394 phase 2a)
//
// This is the typed replacement for sessionManager's structural
// AgentSessionLike + `createSession: unknown` + cast. Provider runtimes
// (ClaudeSession, CodexSession, and any future ones registered through
// registry.main.ts) DECLARE they implement AgentSession so mismatches
// fail at compile time inside the provider, not silently at runtime in
// the manager after an event never fires.
//
// WHY a typed event map (AgentSessionEvents) with a strictly-typed
// on/off/emit interface merge (via the AgentSessionEmitter interface
// below), not a bag of `on(event: string, listener: never[])`:
//   1. The previous shape (`on(event, (...args: never[]) => void)`)
//      documented conformance in prose but enforced NOTHING — a
//      provider could drop `screen`, emit a different payload shape
//      for `jsonl-entry`, or misspell `semantic-event`, and it only
//      showed up as "the feature is silently missing". Every event
//      names, payload types, and cadence is now proven by the type.
//   2. This is the seam a third-provider PR touches — being able to
//      say "the compile error tells you what to emit" is the whole
//      point of #394's phase-1 union-derivation work.
//
// WHY the payload types live HERE (in @shared/types) and not in the
// Claude provider or the headless package:
//   sessionManager historically imported ScreenSnapshot from
//   @providers/claude/runtime/claudeSession and JsonlEntry from the
//   claude-code-headless package, which inverted the dependency arrow:
//   the manager (which is supposed to be provider-neutral) knew Claude's
//   types by name. AgentScreenSnapshot / AgentJsonlEntry below are
//   the neutral homes. They start as structural copies of the Claude
//   shapes (that's the wire contract Codex already speaks too — see
//   CodexSession's `screen` event and JSONL-entry forwarding) so this
//   PR is a *rename with dependency-arrow reversal*, not a semantic
//   change. Widening to accommodate an API-only provider (opencode)
//   is phase-7 work.
//
// WHY this file (not sessionManager.ts):
//   sessionManager.ts is main-process code. providers/*/runtime/*
//   files import from shared to declare they implement the contract.
//   Putting AgentSession in sessionManager would force providers to
//   import main from packages/, creating an import cycle and blocking
//   the dispatch-mode "session runtime runs outside the Electron
//   window" escape hatch (see [[dispatch_mode_planned]]).
// ---------------------------------------------------------------------------

/**
 * Structural TUI-screen snapshot. Historically ScreenSnapshot from the
 * Claude headless package; now the provider-neutral name at the shared
 * boundary. The shape is unchanged because Codex already emits
 * identical events through the same channel — this is a home change,
 * not a semantic change.
 *
 * A future API-only provider (opencode) has no terminal to snapshot;
 * that will be modeled by making the `screen` event optional on the
 * capability side of the contract, not by widening this shape.
 */
export type AgentScreenSnapshot = {
  plain: string
  markdown: string
  recent: string
  recentMarkdown: string
}

/**
 * Wire form of a screen frame on the renderer IPC edge (#746). An alt-screen
 * TUI has no scrollback, so `recent` was byte-identical to `plain` (and
 * `recentMarkdown` to `markdown`) in 100% of recorded Claude frames, and
 * Electron's structured clone serialises each string occurrence separately —
 * every such frame crossed IPC at twice its size. The forwarder omits the
 * duplicate fields; the preload puts them back, so no renderer type or
 * consumer ever sees the optional form. Codex frames, which have real
 * scrollback, pass through unchanged.
 */
export type AgentScreenSnapshotWire = {
  plain: string
  markdown: string
  recent?: string
  recentMarkdown?: string
}

export function aliasScreenSnapshotForWire<T extends AgentScreenSnapshot>(
  snapshot: T,
): Omit<T, 'recent' | 'recentMarkdown'> & AgentScreenSnapshotWire {
  const { recent, recentMarkdown, ...rest } = snapshot
  const wire: Omit<T, 'recent' | 'recentMarkdown'> & AgentScreenSnapshotWire = rest
  if (recent !== snapshot.plain) wire.recent = recent
  if (recentMarkdown !== snapshot.markdown) wire.recentMarkdown = recentMarkdown
  return wire
}

export function expandScreenSnapshotFromWire<T extends AgentScreenSnapshotWire>(
  wire: T,
): T & AgentScreenSnapshot {
  return {
    ...wire,
    recent: wire.recent ?? wire.plain,
    recentMarkdown: wire.recentMarkdown ?? wire.markdown,
  }
}

/**
 * Provider transcript-entry payload. Kept as `Record<string, unknown>`
 * at this seam because Claude and Codex ship entries with fundamentally
 * different shapes on the same event (`type:'user'|'assistant'|...` vs
 * `payload:{...}, type:'response_item'|'event_msg'|...`) and the
 * downstream renderer already narrows by shape — see the four
 * duplicated `isCodexRolloutEntry` sniff sites that phase 2b will
 * kill by promoting a transcript-entry codec onto the registry.
 *
 * Deliberately looser than the headless packages' concrete
 * ClaudeJsonlEntry / CodexRolloutLine so a third provider isn't
 * forced to satisfy Claude's discriminated union at this boundary.
 */
export type AgentTranscriptEntry = Record<string, unknown>

/**
 * Diagnostic identity carried beside a committed provider entry.
 *
 * WHY this is not embedded into `AgentTranscriptEntry`: that object mirrors a
 * provider-owned line and is also used for transcript translation. Mutating it
 * would make app-local observation metadata look native. The optional sidecar
 * keeps older providers and recordings compatible while allowing Codex's
 * coordinator-authorized file generation to remain explicit.
 */
export type AgentTranscriptObservationMetadata = {
  fileGenerationId: string | null
  /** Absolute byte position of the line within the authorized file generation. */
  rolloutByteOffset: number
  /** Provider-owned, privacy-transformed session_meta identity when present. */
  providerSessionMetaFingerprint?: string
}

/** Payload for the process-state event: whether the provider is
 *  actively working, plus an optional human-readable status verb. */
export type AgentProcessState = {
  active: boolean
  status?: string
}

/** Legacy per-condition event payloads. These are still emitted by
 *  ClaudeSession alongside the unified `conditions` snapshot; kept
 *  optional on the contract so a provider that only emits `conditions`
 *  isn't forced to fabricate them (see the deprecation note next to
 *  each in claudeSession.ts). Codex already skips them today. */
export type AgentTrustDialogState = {
  visible: boolean
  workspace?: string
}
export type AgentResumePromptState = {
  visible: boolean
  sessionAgeText?: string
  tokenCountText?: string
  options?: string[]
  selectedIndex?: number
}
export type AgentPermissionPromptState = {
  visible: boolean
  title?: string
  toolName?: string
  command?: string
  options?: Array<{ key: string; label: string }>
  selectedIndex?: number
}
/**
 * The event map every AgentSession implementation must satisfy. Keys
 * are event names as emitted; array values are the argument tuple the
 * listener receives.
 *
 * WHY `semantic-event` carries `unknown` (and NOT a union like
 * ClaudeSemanticEvent | CodexSemanticEvent):
 *   The manager is deliberately provider-agnostic and forwards this
 *   payload verbatim to the renderer, which narrows by `ev.type`.
 *   Encoding the union here would re-couple the manager to every
 *   provider's semantic vocabulary; the whole point of the semantic
 *   channel is that new providers can widen the union without
 *   touching main. See EVENT_SPEC.md in the headless packages.
 *
 * `started.projectDir` is optional because it has provider-defined
 * semantics: Claude's is the per-cwd transcript dir; Codex's is the
 * global sessions root; an API provider may not have a directory
 * concept at all. See #394 §2 on the ambiguity.
 */
/**
 * The event map every AgentSession implementation must satisfy.
 *
 * Keys are event names as emitted; array values are the argument tuple
 * the listener receives.
 *
 * Every provider MUST emit `started`, `exit`, `conditions`,
 * `semantic-event`, and typically `pty-data`/`screen`/`jsonl-entry`/
 * `jsonl-error`/`process-state`/`trust-dialog` (all present on both
 * Claude and Codex today; an API-only provider will have optional
 * variants in phase 7).
 *
 * `resume-prompt` and `permission-prompt` are
 * **legacy per-condition events emitted only by Claude** and slated
 * for removal (see ClaudeSession.ts's own deprecation comment). They
 * are NOT part of the required contract — they live on
 * `AgentLegacyClaudeConditionEvents` below, which providers can
 * declare via TypeScript interface-merging when they still want to
 * emit them (Claude does). Sessionmanager subscribes to them
 * unconditionally through the strictly-typed `on()` signature, so a
 * provider that doesn't emit them simply never fires the callback —
 * no runtime cost, and forces provider authors to make an explicit
 * choice.
 */
/**
 * Durable-history generation boundary payload (grok catalog history.replacement).
 * Provider-neutral on purpose: Codex already has file generations, and any
 * provider whose transcript can be rewritten in place needs the same signal.
 */
export type ProviderHistoryBoundaryEvent = {
  type: 'reset' | 'caught-up'
  generation: number
  snapshotByteLength: number
  byteOffset?: number
  complete?: boolean
}

export type AgentSessionEvents = {
  started: [{ projectDir?: string; proxyUrl?: string }]
  'input-readiness': [AgentInputReadiness]
  /**
   * Optional, diagnostic-only companion to `input-readiness`.
   *
   * `input-readiness` is the CONTRACT — a boolean plus a coarse reason, and the
   * only thing correctness may gate on. This carries the provider's detailed
   * verdict (replay pending, composer unpainted, human draft, blocked on a
   * condition), which `publishPromptGate` otherwise collapses away before main
   * can see it. Those distinctions are three different problems that are
   * indistinguishable in every log we have.
   *
   * Declared optional-by-convention: only Claude emits it today. A provider
   * that doesn't simply never fires the callback, exactly like the legacy
   * condition events below. Nothing may branch on it — a consumer that needs a
   * decision must use `input-readiness`.
   */
  'prompt-gate': [PromptGateState]
  'pty-data': [string]
  screen: [AgentScreenSnapshot]
  'jsonl-entry': [AgentTranscriptEntry, string, AgentTranscriptObservationMetadata?]
  'jsonl-error': [Error]
  /**
   * Diagnostic-only explanation of transcript discovery/ownership decisions.
   * Providers that do not expose one simply never emit it. Correctness must
   * continue to use committed entries and errors; this channel exists so a
   * held candidate is inspectable in a recording instead of looking like a
   * silent transport failure.
   */
  'transcript-diagnostic': [unknown]
  'process-state': [AgentProcessState]
  'trust-dialog': [AgentTrustDialogState]
  conditions: [ProviderConditionSnapshot]
  // A durable-history generation boundary (grok: reset when native rewrote the transcript
  // file, caught-up when the rewrite snapshot is fully delivered; catalog
  // history.replacement). Never turn completion or idle. A rewrite re-delivers
  // many rows under one boundary, so the boundary is its own ordering point
  // rather than a per-entry flag. Sessions emit it from Stage 4; delivery
  // through preload and both SessionFeeds is Stage 5 of the grok plan.
  'history-boundary': [ProviderHistoryBoundaryEvent & { file: string }]
  /**
   * The provider session this pane runs changed WITHOUT a respawn: the user
   * started, resumed or forked a session inside a native TUI that Agent Code
   * follows (Pi: /new, /resume, /fork — decision D4 in
   * docs/decomposition/pi-terminal.md). Emitted BEFORE the provider's own
   * history-boundary reset and the new session's rows, so a consumer has
   * rebound the pane's identity by the time the new conversation arrives.
   *
   * WHY an explicit event and not a new id inside a transcript row: the
   * renderer quarantines any committed burst whose provider id conflicts with
   * the pane's durable one (#290 — duplicated panes rendering each other's
   * messages). A switch the user made on purpose must be distinguishable from
   * that misattach, and only the runtime that watched it happen can say so.
   */
  'provider-session-changed': [{ providerSessionId: string; transcriptFile: string | null; reason: string }]

  'semantic-event': [unknown]
  exit: [{ exitCode: number; signal?: number }]
} & AgentLegacyClaudeConditionEvents

/**
 * Legacy per-condition events. Historically Claude fired individual
 * `resume-prompt` / `permission-prompt` events
 * alongside the unified `conditions` snapshot; Codex never emitted
 * them. Keeping them here (rather than dropping them outright) lets
 * sessionManager keep its current forwarding without touching the
 * `session:*-prompt` IPC channels the renderer still listens to. A
 * follow-up (part of the conditions-v2 phase, #394 phase 3) removes
 * these when the renderer stops needing them.
 *
 * Providers that don't emit them define the listener signatures
 * anyway (via this shape) — the runtime cost is zero (no emit → no
 * callback), and the shared shape lets sessionManager subscribe
 * without a cast.
 */
export type AgentLegacyClaudeConditionEvents = {
  'resume-prompt': [AgentResumePromptState]
  'permission-prompt': [AgentPermissionPromptState]
}

/**
 * Strictly-typed on/off/emit interface merge — the same pattern the
 * headless packages already use for their own class events. Providers
 * that extend `EventEmitter` can declare this via TypeScript's
 * interface-merging (see ClaudeSession/CodexSession for the pattern)
 * without changing runtime behavior.
 */
export interface AgentSessionEmitter {
  on<K extends keyof AgentSessionEvents>(
    event: K,
    listener: (...args: AgentSessionEvents[K]) => void,
  ): this
  off<K extends keyof AgentSessionEvents>(
    event: K,
    listener: (...args: AgentSessionEvents[K]) => void,
  ): this
  once<K extends keyof AgentSessionEvents>(
    event: K,
    listener: (...args: AgentSessionEvents[K]) => void,
  ): this
  removeAllListeners(event?: keyof AgentSessionEvents): this
  emit<K extends keyof AgentSessionEvents>(
    event: K,
    ...args: AgentSessionEvents[K]
  ): boolean
}

/**
 * The behavioral contract every registered agent provider must satisfy.
 *
 * Optional methods encode capabilities that are legitimately
 * provider-specific today. The manager already duck-types them
 * (sessionManager resolveCondition /
 * awaitCodexReadyForPrompt) — declaring them optional here just makes
 * that duck-typing type-checked. Phase 2c generalizes these into a
 * `promptDelivery` capability shape; the individual optional methods
 * survive until then so the phase-2a diff stays a mechanical
 * refactor.
 */
export interface AgentSession extends AgentSessionEmitter {
  start(): Promise<{ projectDir?: string } | void>
  stop(): Promise<void>
  write(data: string): void
  resize(cols: number, rows: number): void

  /** Optional: does the underlying process have a pid we can display /
   *  attribute performance to? Terminal panes obviously do; API-only
   *  providers may not. */
  getProcessPid?(): number | null
  /** Optional: has the underlying process exited? Same rationale. */
  isExited?(): boolean
  /**
   * Optional (proxy-streaming providers): the machine was suspended between
   * `suspendedAt` and `resumedAt` (#963).
   *
   * WHY on the session contract: a stream whose socket died while the lid was
   * closed never receives a transport end, and only the provider's adapter knows
   * which of its flows were silent since before the suspension. The manager fans
   * this out; each runtime decides what "sealing a severed stream" means for its
   * transport. Providers without such state simply do not implement it.
   */
  noteSystemSuspension?(suspension: import('@shared/types/systemSuspension.js').SystemSuspension): void
  /**
   * Optional startup-time durable provider identity.
   *
   * Most providers discover this later from transcript traffic. A native
   * OpenCode TUI must pre-create the session before PTY spawn, so it can return
   * the id immediately and avoid losing it in the spawn-IPC/event ordering gap.
   */
  getProviderSessionId?(): string | null

  /** Optional (Claude today): drive a screen-derived condition action
   *  through the provider's own driver. Codex has no equivalent and
   *  routes actions through raw `write` today; opencode uses HTTP
   *  permission replies. Phase 3 (conditions v2) generalizes this.
   *
   *  The result type is loose (`{ ok: true; state?: unknown } |
   *  { ok: false; reason: string; ... }`) at this seam so this
   *  contract doesn't depend on sessionManager (that would create an
   *  import cycle). The concrete shape lives with the resolver call
   *  site in sessionManager.ts's exported ResolveConditionResult. */
  resolveCondition?(
    action: import('@shared/types/providerConditions.js').ConditionCustomAction,
  ): Promise<
    | { ok: true; state?: unknown }
    | { ok: false; reason: string; lastState?: unknown; failedAtStep?: string }
  >

  /** Optional (OpenCode Terminal today): scroll the provider's OWN transcript
   *  view to its newest message. For a TUI that pages its transcript on the
   *  alternate screen, xterm's scrollToBottom cannot move anything (#843). The
   *  provider must use a rebinding-proof route; a user-configurable chord is
   *  not one. Never throws. */
  jumpToLatest?(): Promise<{ ok: true } | { ok: false; reason: string }>

  /** Optional (Claude today): a synchronous read of the live plain-text TUI
   *  screen (headless snapshotPlain). The prompt-delivery path polls this to
   *  detect the paste-commit *transition* — a NEW `[Pasted text #N]`
   *  placeholder OR the paste's tail newly inlined — before firing Enter, the
   *  same content-match signal the desktop composer uses. Returns '' when the
   *  headless instance isn't up yet. */
  snapshotScreen?(): string

  /** Optional (Claude today): the screen and the composer's cell-attribute
   *  counts read from the LIVE buffer at the same instant (#1291/#1309). Not
   *  the per-frame cached classification the prompt gate uses: the delivery
   *  rollback verifies its own keystroke 25 ms later, faster than that cache
   *  moves. Null when the headless instance isn't up. */
  readComposer?(): { screen: string; attributes: { dim: number; inverse: number; plain: number } | null } | null

  /**
   * Optional (Claude today): arm an authoritative prompt-acceptance waiter
   * BEFORE Enter is written. Claude acknowledges a finished prompt through
   * either a `type: "user"` JSONL entry (new turn) or a
   * `queue-operation/enqueue` entry (Claude was already working). Keeping the
   * arm synchronous closes the fastest possible race: a local JSONL append can
   * arrive immediately after the PTY consumes Enter, before an `await` resumes.
   *
   * The returned cancel function is load-bearing on absorption failure. A
   * paste that never reaches the Enter phase must not leave a content-bearing
   * waiter alive to accidentally match a later manual submission.
   */
  armPromptAcceptance?(
    prompt: string,
    opts?: {
      timeoutMs?: number
      aliases?: string[]
      requiresImage?: boolean
      expectedImageCount?: number
    },
  ): PromptAcceptanceWaiter

  /** Claude's bootstrap JSONL replay must quiesce before a new waiter can be
   * armed, otherwise a historical identical entry can acknowledge new bytes. */
  isPromptAcceptanceReady?(): boolean

  /** Optional provider-owned readiness boundary before prompt bytes may be
   *  written. `deadlineAt` is absolute so readiness cannot quietly consume a
   *  fresh timeout budget that later delivery phases also assume they own. */
  awaitReadyForPrompt?(
    opts?: { deadlineAt?: number; timeoutMs?: number; pollIntervalMs?: number },
  ): Promise<PromptReadinessOutcome>

  /** Optional (OpenCode today): deliver a user prompt through the concrete
   *  runtime's transport. Structured OpenCode uses HTTP; OpenCode Terminal
   *  performs a readiness-gated bracketed paste into its PTY. Keeping both
   *  behind one provider-owned capability lets SessionManager stay ignorant
   *  of which OpenCode runtime was selected. Claude/Codex leave it undefined
   *  and their provider policies write through io.write instead. */
  deliverPromptText?(text: string): Promise<void>
}

export type PromptAcceptanceOutcome =
  | { kind: 'user'; acceptedAt: number; entryId?: string }
  | { kind: 'queue'; acceptedAt: number }
  /**
   * `nearMisses`: how many candidate entries each acceptance filter rejected
   * while this waiter starved. Diagnostic-only, but load-bearing for the
   * journal: the 2026-08-30 corpus showed 21/21 acceptance-timeouts were
   * false (the entry existed; a filter dropped it), and none of that was
   * visible from the timeout alone. Optional purely for back-compat: the one
   * timeout constructor (ClaudeSession.armPromptAcceptance) always attaches
   * it, but existing tests and shims build bare `{ kind: 'timeout' }`
   * literals, and requiring the field would force every one of them to
   * fabricate tallies they never measured.
   */
  | {
      kind: 'timeout'
      nearMisses?: { cursor: number; timestamp: number; image: number; exact: number }
    }
  | { kind: 'cancelled' }
  | { kind: 'session-exited' }

export type PromptAcceptanceWaiter = {
  promise: Promise<PromptAcceptanceOutcome>
  cancel: () => void
}

/**
 * Provider-owned prompt gate. Warming states are expected to resolve without
 * user action; every other non-ready state is returned immediately so callers
 * can report the real obstruction instead of spending an arbitrary timeout.
 */
export type PromptGateState =
  | { kind: 'ready' }
  | { kind: 'warming'; reason: 'replay-pending' | 'composer-unpainted' }
  | { kind: 'blocked'; condition: string; resolvable: boolean }
  | { kind: 'occupied'; reason: 'human-draft' }
  | { kind: 'terminal'; reason: 'exited' | 'no-headless' }

export type PromptReadinessOutcome =
  | { kind: 'ready'; waitedMs: number }
  | { kind: 'timeout'; waitedMs: number; lastState: Extract<PromptGateState, { kind: 'warming' }> }
  | Exclude<PromptGateState, { kind: 'ready' } | { kind: 'warming' }>


// Base session types that all providers implement. The shell and main
// process only interact with sessions through these types — never
// through provider-specific session classes directly.
//
// Why these live in shared/ instead of in each provider:
//   The shell (workspaceStore, sessionManager, IPC handlers) needs to
//   talk about sessions generically. These types are the contract.
//   Provider-specific session classes implement/extend them.

export type SessionOptions = {
  cwd: string
  cols?: number
  rows?: number
  binary?: string
  env?: Record<string, string | undefined>
  snapshotIntervalMs?: number
  resumeSessionId?: string
  dangerousMode?: boolean
  /** Stable Agent Code session id assigned by SessionManager. Provider
   *  runtimes can use this for app-owned artifact storage paths
   *  without coupling themselves to the manager implementation. */
  shellSessionId?: string
  /** Opt-in mitmproxy-backed transport capture. Currently only the
   *  Claude provider honors this — Codex ignores it. Declared here
   *  (rather than cast inline at the spawn site) so the contract is
   *  visible to every provider and TypeScript doesn't silently lose
   *  the field the next time the spawn shape changes. */
  useProxy?: boolean
  /** Per-process MCP server configs minted by main for built-in Agent Code
   *  domains. Providers only receive concrete launch material (URL + headers),
   *  never the long-lived domain policy; the renderer/session metadata remains
   *  the source of truth for which domains should be enabled. */
  builtInMcpServers?: BuiltInMcpServerConfig[]
  /** User MCP servers (#1143) already validated, secret-resolved and filtered
   *  by main for this launch and this provider. Providers only translate them;
   *  they never decide which ones apply. */
  userMcpServers?: ResolvedUserMcpServer[]
  /** Codex only: how to send shell exclusions for the user-server secrets it
   *  carries, matching the user's own config (see CodexShellPolicyStyle). */
  userMcpCodexShellPolicy?: { style: 'filters' } | { style: 'legacy'; exclude: readonly string[] }
  /**
   * Main-owned one-shot boundary invoked by a resumed provider immediately
   * before it acquires exclusive durable-transcript ownership.
   *
   * WHY this callback is internal launch material rather than renderer IPC:
   * successor proxy/config/MCP setup does not conflict with a live predecessor,
   * while Codex's exact rollout reservation does. Only the provider knows the
   * last safe await before that reservation; only SessionManager may decide
   * which local pane can be stopped or compensated. Passing a closure joins
   * those two facts without teaching the provider about pane IDs or weakening
   * the consumer-independent rollout coordinator. Providers without an exact
   * ownership boundary ignore it.
   */
  beforeResumeOwnershipAcquire?: () => Promise<void>
}

export type SessionHistoryChunk = {
  entries: AgentTranscriptEntry[]
  hasMore: boolean
  // Only set on initial-load chunks. See `HistoryChunk.totalEntries`
  // in src/main/sessions/historyLoader.ts for the full WHY. Renderers
  // should treat absence as "unknown / not provided" and avoid using
  // it as a denominator unless it's a positive number.
  totalEntries?: number
  // Byte offset of each entry's transcript line, parallel to `entries`.
  // The renderer echoes the one for its pagination cursor line back as
  // `beforeOffset`. See `HistoryChunk.offsets` in historyLoader.ts.
  offsets?: number[]
}

